#include <vector>
#include <cstddef>
#include <omp.h>

size_t findFirstEven(std::vector<int> const& x) {
    const size_t n = x.size();
    size_t best = n; // n means "not found"

    #pragma omp parallel
    {
        size_t local_best = n;

        #pragma omp for nowait
        for (size_t i = 0; i < n; ++i) {
            if ((x[i] % 2) == 0) {
                if (i < local_best) local_best = i;
            }
        }

        #pragma omp critical
        {
            if (local_best < best) best = local_best;
        }
    }

    return best;
}
